    Date stopDepartureTime = stop.getDepartureTime();
    if (stopArrivalTime == null || stopDepartureTime == null)
    {
      return false;
    }
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    sdf.setLenient(false);
    String arrivalStr;
